<template>
  <main class="sole-page" :aria-busy="loading">
    <header class="sole-heading">
      <div><span class="sole-eyebrow"><i class="bi bi-layers" aria-hidden="true"></i> Планування запасів</span><h1>Запас підошви</h1><p>Відправлення з CRM → витрата підошви → наступне замовлення з Китаю.</p></div>
      <button class="btn sole-button" :disabled="loading || saving" @click="load"><i class="bi bi-arrow-clockwise" aria-hidden="true"></i> {{ loading ? 'Оновлюємо…' : 'Оновити' }}</button>
    </header>
    <div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div>
    <div v-if="notice" class="alert alert-success" role="status">{{ notice }}</div>
    <p v-if="loading && !report" class="sole-empty" role="status">Рахуємо відправлені пари…</p>
    <template v-if="report">
      <div v-if="report.missing_categories.length" class="alert alert-warning">Не знайдено категорії CRM: {{ report.missing_categories.join(', ') }}. Дані з інших категорій не підставляємо.</div>
      <section class="sole-metrics" aria-label="Підсумок запасу">
        <article><div><span>Розрахунковий залишок</span><strong>{{ report.totals.configured_sizes ? number(report.totals.remaining) : '—' }} <small>пар</small></strong><p>Внесено {{ report.totals.configured_sizes }} із {{ report.totals.total_sizes }} залишків за розмірами</p></div><i class="bi bi-box-seam" aria-hidden="true"></i></article>
        <article><div><span>Час замовляти</span><strong>{{ report.totals.order_now }} <small>розмірів</small></strong><p>З урахуванням поставки та запасу часу</p></div><i class="bi bi-truck" aria-hidden="true"></i></article>
        <article><div><span>Джерело витрати</span><strong class="sole-metric-text">Відправлені пари</strong><p>1 пара капців = 1 пара підошви</p></div><i class="bi bi-check2-circle" aria-hidden="true"></i></article>
      </section>
      <div v-if="report.totals.configured_sizes < report.totals.total_sizes" class="sole-onboarding"><i class="bi bi-info-circle" aria-hidden="true"></i><div><strong>Почніть із залишків</strong><p>Внесіть запас на початок обраного дня та повний термін поставки: виробництво + доставка з Китаю. Порожній залишок — невідомий, а не нуль.</p></div></div>

      <section v-for="category in report.categories" :key="category.id" class="sole-card" :aria-labelledby="`category-${category.id}`">
        <header class="sole-card-heading"><div><h2 :id="`category-${category.id}`">{{ category.name }}</h2><p>{{ category.settings.lookback_days }} повних днів · {{ date(category.window_from) }} — {{ date(category.window_to) }} <span v-if="category.settings.lead_time_days !== null">· Поставка {{ category.settings.lead_time_days }} дн. + резерв {{ category.settings.safety_days }} дн.</span></p></div><div class="sole-actions"><button class="btn sole-button" :disabled="saving || loading" :aria-expanded="editor?.categoryId === category.id && editor?.type === 'plan'" @click="openPlan(category)"><i class="bi bi-sliders" aria-hidden="true"></i> {{ category.settings.version ? 'Налаштувати' : 'Внести залишки' }}</button><button class="btn sole-button" :disabled="saving || loading || !category.settings.version" :aria-expanded="editor?.categoryId === category.id && editor?.type === 'movement'" @click="openMovement(category)"><i class="bi bi-plus-lg" aria-hidden="true"></i> Рух запасу</button></div></header>

        <form v-if="editor?.categoryId === category.id" class="sole-editor" @submit.prevent="save">
          <fieldset :disabled="saving"><legend>{{ editor.type === 'plan' ? 'Залишки та прогноз' : 'Надходження / коригування' }}</legend>
            <template v-if="editor.type === 'plan'">
              <p>Залишки вказуйте <strong>на початок дня</strong>: відправлення від цієї дати включно будуть відняті. Це розрахункова база, а не склад готових капців.</p>
              <div class="sole-form-grid">
                <label>Дата початкового залишку<input v-model="form.opening_date" type="date" class="form-control" required min="2020-01-01" :max="report.today" data-testid="opening-date" /></label>
                <label>Поставка з Китаю, днів<input v-model="form.lead_time_days" type="number" class="form-control" min="1" max="730" placeholder="Укажіть термін" data-testid="lead-time" /></label>
                <label>Запас часу, днів<input v-model="form.safety_days" type="number" class="form-control" required min="0" max="365" /></label>
                <label>Темп відправлень за<select v-model="form.lookback_days" class="form-select"><option :value="30">30 повних днів</option><option :value="60">60 повних днів</option><option :value="90">90 повних днів</option></select></label>
              </div>
              <div class="sole-balances"><label v-for="balance in form.opening_balances" :key="balance.size">{{ balance.size }} <span>· пар підошви</span><input v-model="balance.quantity" type="number" class="form-control" min="0" max="10000000" placeholder="Не внесено" :data-size="balance.size" /></label></div>
              <small v-if="category.settings.version">Зміна початкового залишку перерахує історію. Для браку, інвентаризації та повторного продажу готового повернення використовуйте «Рух запасу → Коригування».</small>
            </template>
            <template v-else>
              <p>Додавайте лише підошву, яка вже надійшла. Партії в дорозі ще не збільшують залишок.</p>
              <div class="sole-form-grid">
                <label>Операція<select v-model="form.kind" class="form-select" data-testid="movement-kind"><option value="receipt">Надходження</option><option value="adjustment">Коригування (+ / −)</option></select></label>
                <label>Розмір<select v-model="form.size" class="form-select"><option v-for="row in category.rows" :key="row.size" :value="row.size" :disabled="row.opening_quantity === null">{{ row.size }}{{ row.opening_quantity === null ? ' · немає залишку' : '' }}</option></select></label>
                <label>Кількість пар<input v-model="form.quantity" type="number" class="form-control" required :min="form.kind === 'receipt' ? 1 : -10000000" max="10000000" data-testid="movement-quantity" /></label>
                <label>Дата руху<input v-model="form.movement_date" type="date" class="form-control" required :min="category.settings.opening_date" :max="report.today" /></label>
              </div>
              <label class="sole-note-label">{{ form.kind === 'adjustment' ? 'Причина коригування (обов’язково)' : 'Примітка' }}<input v-model="form.note" class="form-control" maxlength="500" :required="form.kind === 'adjustment'" placeholder="Наприклад, отримали партію з Китаю" /></label>
              <small>Плюс додає пари, мінус списує. Записи зберігаються в журналі; помилковий рух виправляйте зворотним коригуванням.</small>
            </template>
            <div v-if="formError" class="alert alert-danger mt-3 mb-0" role="alert">{{ formError }}</div>
            <div class="sole-form-actions"><button class="btn btn-primary" type="submit">{{ saving ? 'Зберігаємо…' : 'Зберегти' }}</button><button class="btn sole-button" type="button" @click="editor = null">Скасувати</button></div>
          </fieldset>
        </form>

        <div class="sole-table-scroll"><table class="sole-table"><caption class="visually-hidden">Залишки та прогноз для {{ category.name }}</caption><thead><tr><th scope="col">Розмір</th><th scope="col">Залишок, пар</th><th scope="col">Відправлено</th><th scope="col">Пар / день</th><th scope="col">Вистачить на</th><th scope="col">Замовити до</th><th scope="col">Стан</th></tr></thead><tbody><tr v-for="row in category.rows" :key="row.size"><th scope="row">{{ row.size }}</th><td><strong :class="{ 'sole-negative': row.remaining !== null && row.remaining < 0 }">{{ number(row.remaining) }}</strong><small v-if="row.opening_quantity !== null" class="sole-equation">{{ number(row.opening_quantity) }} + ({{ number(row.movements_quantity) }}) − {{ number(row.consumed) }}</small></td><td>{{ number(row.shipped_in_window) }} <small>пар</small></td><td>{{ number(row.daily_rate) }}</td><td>{{ row.days_remaining === null ? '—' : `${number(row.days_remaining)} дн.` }}<small v-if="row.depletion_date" class="sole-equation">до {{ date(row.depletion_date) }}</small></td><td>{{ date(row.reorder_date) }}<small v-if="row.reorder_point !== null" class="sole-equation">Мін. запас {{ number(row.reorder_point) }} пар</small></td><td><span class="sole-status" :class="`sole-status-${row.status}`">{{ statusLabels[row.status] }}</span></td></tr></tbody></table></div>

        <div v-if="hasWarnings(category)" class="sole-data-warning"><strong>Є дані для перевірки</strong><p v-if="category.warnings.unknown_size_pairs">Не розпізнано розмір: {{ category.warnings.unknown_size_pairs }} пар. Вони не відняті від залишків.</p><p v-if="category.warnings.missing_date_orders">Без дати відправлення: {{ category.warnings.missing_date_orders }} замовлень за всю історію — не враховані.</p><p v-if="category.warnings.duplicate_orders">Дублі ТТН: {{ category.warnings.duplicate_orders }} замовлень пропущено.</p><details v-if="category.issues.length"><summary>Показати замовлення (до 10)</summary><ul><li v-for="(issue, i) in category.issues" :key="i"><a :href="`/orders/${issue.order_id}`" target="_blank" rel="noopener">№ {{ issue.order_number }}</a> — {{ issue.message }}</li></ul></details></div>
        <p v-if="category.warnings.approximate_date_pairs || category.warnings.without_ttn_orders" class="sole-data-note">{{ category.warnings.approximate_date_pairs }} пар із приблизною датою відправлення; {{ category.warnings.without_ttn_orders }} замовлень без ТТН. Деталі методики — нижче.</p>
        <p v-if="report.history_available_from && report.history_available_from.slice(0, 10) > category.window_from" class="sole-data-warning">Історія трекінгу починається {{ date(report.history_available_from.slice(0, 10)) }}. Частина періоду може бути неповною, тому прогноз може бути занижений.</p>
        <details class="sole-detail"><summary>Динаміка та останні відправлення</summary><div class="sole-trend" role="img" :aria-label="`Відправлено ${category.rows.reduce((sum, row) => sum + row.shipped_in_window, 0)} пар за ${category.settings.lookback_days} днів`"><div v-for="day in category.trend" :key="day.date" class="sole-bar-slot" :title="`${date(day.date)}: ${day.quantity} пар`"><div class="sole-bar" :style="{ height: `${Math.max(day.quantity ? 3 : 0, day.quantity / Math.max(1, ...category.trend.map(d => d.quantity)) * 100)}%` }"></div></div></div><div class="sole-trend-labels"><span>{{ date(category.window_from) }}</span><span>Відправлені пари · без сьогоднішнього неповного дня</span><span>{{ date(category.window_to) }}</span></div><p v-if="!category.recent_shipments.length" class="sole-data-note">Відправлень у розрахунковому періоді немає.</p><div v-else class="sole-table-scroll"><table class="sole-table sole-journal"><caption>Останні 20 товарних позицій у розрахунковому періоді</caption><thead><tr><th>Дата фіксації</th><th>Замовлення</th><th>Розмір</th><th>Пар</th></tr></thead><tbody><tr v-for="(shipment, i) in category.recent_shipments" :key="i"><td>{{ date(shipment.date) }}{{ shipment.approximate_date ? ' ≈' : '' }}</td><td><a :href="`/orders/${shipment.order_id}`" target="_blank" rel="noopener">№ {{ shipment.order_number }}</a></td><td>{{ shipment.size }}</td><td>{{ shipment.quantity }}</td></tr></tbody></table></div></details>
      </section>

      <section class="sole-card sole-method"><h2>Як рахуємо</h2><p><strong>Залишок = початковий запас + надходження ± коригування − відправлені пари.</strong> Категорія береться з пов’язаного товару CRM, кількість і розмір — із позиції замовлення; якщо розмір порожній — із пов’язаного варіанта.</p><p>Враховуємо першу зафіксовану ознаку відправлення в історії доставки або статусів CRM, незалежно від поточного статусу. Сама створена ТТН, пакування та нові замовлення не списують запас. Одна ТТН — одне замовлення; серед дублів береться найстаріше з підтвердженням відправлення.</p><p>Якщо збереглося лише прибуття, отримання чи повернення, дата приблизна. За відсутності історії використовуємо дату поточного статусу відправлення / завершення; дату створення замовлення не підставляємо. Записи без дати показуємо окремо.</p><p>Повернення готових капців не відновлює сировину. Повторний продаж тієї самої готової пари потребує ручного коригування (+1 пара), якщо вона вже була врахована. Виробництво наперед, брак і сезонність цей прогноз автоматично не визначає — звіряйте запас інвентаризацією.</p><p>Темп = відправлені пари ÷ усі календарні дні обраного періоду, без сьогодні. Дата замовлення = прогноз закінчення − термін поставки − резерв часу. Рекомендований початковий резерв — 14 днів, його можна змінити. За нульового темпу дату не прогнозуємо.</p><p v-if="report.unlinked_item_count" class="sole-data-warning">У CRM є {{ report.unlinked_item_count }} позицій без пов’язаного товару (за всю історію, усі категорії). Їх неможливо надійно віднести до підошви, тому вони не враховані.</p><p class="sole-data-note">Це оперативна оцінка за поточними даними CRM, не виробничий облік. Редагування товарів чи старих позицій замовлення може змінити розрахунок. Сайт-магазин не використовується.</p></section>
      <section class="sole-card sole-method"><h2>Журнал руху запасу</h2><p v-if="!report.journal.length" class="sole-data-note">Надходжень і коригувань поки немає.</p><div v-else class="sole-table-scroll"><table class="sole-table sole-journal"><caption>Останні 30 записів. Початкові залишки редагуються в налаштуваннях категорії.</caption><thead><tr><th>Дата</th><th>Категорія / розмір</th><th>Операція</th><th>Пар</th><th>Примітка</th></tr></thead><tbody><tr v-for="entry in report.journal" :key="entry.id"><td>{{ date(entry.movement_date) }}</td><td>{{ categoryName(entry.category_id) }} · {{ entry.size }}</td><td>{{ entry.kind === 'receipt' ? 'Надходження' : 'Коригування' }}</td><td>{{ entry.quantity > 0 ? '+' : '' }}{{ number(entry.quantity) }}</td><td>{{ entry.note || '—' }}</td></tr></tbody></table></div></section>
      <footer class="sole-footer">Оновлено {{ new Date(report.as_of).toLocaleString('uk-UA', { timeZone: 'Europe/Kyiv' }) }} · час Києва</footer>
    </template>
  </main>
</template>

<script setup>
import { onMounted, ref } from 'vue';
import { fetchSoleInventory, saveSolePlan, addSoleMovement, inventoryError } from '@/crm/services/soleInventoryApi';

const report = ref(null), loading = ref(false), saving = ref(false), error = ref(''), notice = ref('');
const editor = ref(null), form = ref({}), formError = ref('');
const statusLabels = { unconfigured: 'Внесіть залишок', depleted: 'Запас вичерпано', no_history: 'Немає темпу', missing_lead: 'Укажіть поставку', order_now: 'Замовляти зараз', sufficient: 'Запас є' };
const number = value => value === null || value === undefined ? '—' : Number(value).toLocaleString('uk-UA', { maximumFractionDigits: 2 });
const date = value => value ? value.slice(0, 10).split('-').reverse().join('.') : '—';
const categoryName = id => report.value.categories.find(category => category.id === id)?.name || 'Категорія';
const hasWarnings = category => category.warnings.unknown_size_pairs || category.warnings.missing_date_orders || category.warnings.duplicate_orders;
const nullableInteger = value => value === '' || value === null ? null : Number(value);

async function load() {
  if (loading.value) return;
  loading.value = true; error.value = '';
  try { report.value = (await fetchSoleInventory()).data; }
  catch (err) { error.value = `${inventoryError(err)}${report.value ? ' На екрані попередні дані.' : ''}`; }
  finally { loading.value = false; }
}
function openPlan(category) {
  if (editor.value?.categoryId === category.id && editor.value?.type === 'plan') { editor.value = null; return; }
  editor.value = { categoryId: category.id, type: 'plan' }; formError.value = ''; notice.value = '';
  form.value = { ...category.settings, opening_date: category.settings.opening_date || report.value.today,
    opening_balances: category.rows.map(row => ({ size: row.size, quantity: row.opening_quantity })) };
}
function openMovement(category) {
  if (editor.value?.categoryId === category.id && editor.value?.type === 'movement') { editor.value = null; return; }
  editor.value = { categoryId: category.id, type: 'movement' }; formError.value = ''; notice.value = '';
  form.value = { request_key: crypto.randomUUID(), size: category.rows.find(row => row.opening_quantity !== null)?.size || '', kind: 'receipt', quantity: '', movement_date: report.value.today, note: '' };
}
async function save() {
  if (saving.value) return;
  saving.value = true; formError.value = ''; notice.value = '';
  try {
    if (editor.value.type === 'plan') {
      await saveSolePlan(editor.value.categoryId, { ...form.value,
        lead_time_days: nullableInteger(form.value.lead_time_days), safety_days: Number(form.value.safety_days), lookback_days: Number(form.value.lookback_days),
        opening_balances: form.value.opening_balances.map(row => ({ ...row, quantity: nullableInteger(row.quantity) })) });
    } else {
      await addSoleMovement(editor.value.categoryId, { ...form.value, quantity: Number(form.value.quantity), note: form.value.note || null });
    }
    editor.value = null; notice.value = 'Збережено. Залишки та прогноз перераховано.';
    await load();
    if (error.value) notice.value = 'Запис збережено. Натисніть «Оновити», щоб отримати новий розрахунок.';
  } catch (err) { formError.value = inventoryError(err); }
  finally { saving.value = false; }
}
onMounted(load);
</script>

